ALTER TABLE `erp_stock_movements` ADD CONSTRAINT `erp_stock_movements_reason_source_consistent` CHECK ((`erp_stock_movements`.`reason` in ('opening_stock', 'count_correction', 'wastage', 'damage') and `erp_stock_movements`.`source_type` = 'adjustment') or (`erp_stock_movements`.`reason` in ('sale', 'purchase', 'purchase_cancellation', 'refund', 'void', 'transfer_in') and `erp_stock_movements`.`reason` = `erp_stock_movements`.`source_type`) or (`erp_stock_movements`.`reason` in ('consumable_reserve', 'consumable_return') and `erp_stock_movements`.`source_type` = 'consumable_transfer'));--> statement-breakpoint
ALTER TABLE `erp_stock_movements` ADD CONSTRAINT `erp_stock_movements_direction_consistent` CHECK (`erp_stock_movements`.`reason` = 'count_correction' or (`erp_stock_movements`.`reason` in ('wastage', 'damage', 'sale', 'purchase_cancellation', 'consumable_reserve') and `erp_stock_movements`.`quantity_delta` < 0) or (`erp_stock_movements`.`reason` in ('opening_stock', 'purchase', 'refund', 'void', 'transfer_in', 'consumable_return') and `erp_stock_movements`.`quantity_delta` > 0));